.version 7.8
.target sm_89
.address_size 64

.visible .entry matmul_kernel(
    .param .u64 matmul_A,
    .param .u64 matmul_B,
    .param .u64 matmul_C,
    .param .u32 matmul_M,
    .param .u32 matmul_N,
    .param .u32 matmul_K
)
{
    .reg .pred %p<8>;
    .reg .b32 %r<48>;
    .reg .b64 %rd<16>;
    .reg .f32 %f<16>;

    .shared .align 4 .b8 sA[1024];
    .shared .align 4 .b8 sB[1024];

    ld.param.u64 %rd1, [matmul_A];
    ld.param.u64 %rd2, [matmul_B];
    ld.param.u64 %rd3, [matmul_C];
    ld.param.u32 %r1, [matmul_M];
    ld.param.u32 %r2, [matmul_N];
    ld.param.u32 %r3, [matmul_K];

    mov.u32 %r4, %tid.x;
    mov.u32 %r5, %tid.y;
    mov.u32 %r6, %ctaid.x;
    mov.u32 %r7, %ctaid.y;

    shl.b32 %r8, %r6, 4;
    add.u32 %r9, %r8, %r4;
    shl.b32 %r10, %r7, 4;
    add.u32 %r11, %r10, %r5;

    mov.f32 %f1, 0f00000000;
    mov.f32 %f10, 0f00000000;

    mov.u32 %r12, 0;

LOOP_K:
    setp.ge.u32 %p1, %r12, %r3;
    @%p1 bra DONE;

    add.u32 %r13, %r12, %r4;
    setp.lt.u32 %p2, %r11, %r1;
    setp.lt.u32 %p3, %r13, %r3;
    and.pred %p4, %p2, %p3;
    mul.lo.u32 %r14, %r11, %r3;
    add.u32 %r15, %r14, %r13;
    mul.wide.u32 %rd4, %r15, 4;
    add.u64 %rd5, %rd1, %rd4;
    mov.f32 %f2, 0f00000000;
    @%p4 ld.global.f32 %f2, [%rd5];
    shl.b32 %r16, %r5, 4;
    add.u32 %r17, %r16, %r4;
    shl.b32 %r18, %r17, 2;
    mov.u32 %r19, sA;
    add.u32 %r20, %r19, %r18;
    st.shared.f32 [%r20], %f2;

    add.u32 %r21, %r12, %r5;
    setp.lt.u32 %p5, %r21, %r3;
    setp.lt.u32 %p6, %r9, %r2;
    and.pred %p7, %p5, %p6;
    mul.lo.u32 %r22, %r21, %r2;
    add.u32 %r23, %r22, %r9;
    mul.wide.u32 %rd6, %r23, 4;
    add.u64 %rd7, %rd2, %rd6;
    mov.f32 %f3, 0f00000000;
    @%p7 ld.global.f32 %f3, [%rd7];
    mov.u32 %r24, sB;
    add.u32 %r25, %r24, %r18;
    st.shared.f32 [%r25], %f3;

    bar.sync 0;

    mov.u32 %r26, 0;

LOOP_I:
    setp.ge.u32 %p1, %r26, 16;
    @%p1 bra LOOP_I_END;

    shl.b32 %r27, %r5, 4;
    add.u32 %r28, %r27, %r26;
    shl.b32 %r29, %r28, 2;
    mov.u32 %r30, sA;
    add.u32 %r31, %r30, %r29;
    ld.shared.f32 %f4, [%r31];

    shl.b32 %r32, %r26, 4;
    add.u32 %r33, %r32, %r4;
    shl.b32 %r34, %r33, 2;
    mov.u32 %r35, sB;
    add.u32 %r36, %r35, %r34;
    ld.shared.f32 %f5, [%r36];

    mul.f32 %f6, %f4, %f5;
    sub.f32 %f7, %f6, %f10;
    add.f32 %f8, %f1, %f7;
    sub.f32 %f9, %f8, %f1;
    sub.f32 %f10, %f9, %f7;
    mov.f32 %f1, %f8;

    add.u32 %r26, %r26, 1;
    bra LOOP_I;

LOOP_I_END:
    bar.sync 0;
    add.u32 %r12, %r12, 16;
    bra LOOP_K;

DONE:
    setp.lt.u32 %p2, %r11, %r1;
    setp.lt.u32 %p3, %r9, %r2;
    and.pred %p4, %p2, %p3;
    mul.lo.u32 %r37, %r11, %r2;
    add.u32 %r38, %r37, %r9;
    mul.wide.u32 %rd8, %r38, 4;
    add.u64 %rd9, %rd3, %rd8;
    @%p4 st.global.f32 [%rd9], %f1;

    ret;
}
